-- Insertar productos (upsert por SKU). Ejecutar en Supabase -> SQL Editor.
create unique index if not exists productos_sku_uidx on productos (sku);

on conflict (sku) do update set
  categoria=excluded.categoria,
  cod_categoria=excluded.cod_categoria,
  subcategoria=excluded.subcategoria,
  cod_subcategoria=excluded.cod_subcategoria,
  correlativo=excluded.correlativo,
  tipo=excluded.tipo,
  asignacion=excluded.asignacion,
  nombre_clave=excluded.nombre_clave,
  marca=excluded.marca,
  modelo=excluded.modelo,
  codigo_barras=excluded.codigo_barras;
